import { readFileSync } from 'node:fs'
import path from 'node:path'
import type { Plugin } from 'vite'
import { DSH_REACT_GLOBAL } from './react.js'

/**
 * Minimal structural declaration of rollup's output.
 *
 * We do not import rollup's types directly: `vite` does not re-export them, and pulling
 * rollup in as a dependency for a build plugin is not worth it. Only the fields this
 * plugin actually reads and writes are declared here.
 */
interface DshOutputChunk {
  type: 'chunk'
  fileName: string
  code: string
  map?: unknown
  /** Module ids of static imports reported by rollup (including externals). */
  imports?: readonly string[]
  /** Module ids of dynamic import() calls. */
  dynamicImports?: readonly string[]
}

interface DshOutputAsset {
  type: 'asset'
  fileName: string
}

type DshOutputBundle = Record<string, DshOutputChunk | DshOutputAsset>

/** Built-in platform modules: provided by DSH's module table, never allowed into the artifact. */
const DEFAULT_PLATFORM_MODULES = ['react'] as const

export interface DshBundleOptions {
  /** Browser module id; defaults to the owning package.json's name. */
  id?: string
  /**
   * Client entry. When given, `build.lib` (cjs / single file) is filled in for you;
   * when omitted, the consumer's own build config is left untouched.
   */
  entry?: string
  /** Extra platform modules to keep external; `react` is included by default. */
  platformModules?: readonly string[]
  /** Artifact file name; defaults to `client.js`. */
  fileName?: string
  /** Disable the React bootstrap injection (only needed if you call `useDshReact` yourself). Enabled by default. */
  react?: boolean
}

/**
 * Wraps rollup's CJS output into one factory registration of DSH's client module system.
 *
 * Artifact shape:
 * ```js
 * window.__ModuleLoader__.load({ id: '<package name>', factory: function (require) {
 *   "use strict";
 *   var module = { exports: {} }; var exports = module.exports;
 *   globalThis.__VOBS_DSH_REACT__ = require('react');   // platform module, not bundled
 *   ...original bundle...
 *   return module.exports.default ?? module.exports;
 * }});
 * ```
 *
 * @param code - CJS code produced by rollup
 * @param id - browser module identity, i.e. the package name
 * @param options - skip the bootstrap injection when `react: false`
 */
export function wrapAsModuleLoaderFactory(code: string, id: string, options: { react?: boolean } = {}): string {
  const body = code
    .replace(/^['"]use strict['"];?\s*\n?/u, '')
    .replace(/\/\/# sourceMappingURL=.*$/gmu, '')
    .trimEnd()

  const bootstrap =
    options.react === false
      ? ''
      : `globalThis[${JSON.stringify(DSH_REACT_GLOBAL)}]=require("react");\n`

  return `// Generated by @vobs/dsh's dshBundle(); do not edit by hand — rebuild after changing src/.
// DSH client module protocol: registers the factory only; module side effects are deferred to first materialization.
window.__ModuleLoader__.load({id:${JSON.stringify(id)},factory:function(require){
"use strict";
var module={exports:{}};var exports=module.exports;
${bootstrap}${body}
var out=module.exports;
return (out&&out.__esModule&&Object.prototype.hasOwnProperty.call(out,"default"))?out.default:out;
}});
`
}

/** Merges the consumer's external config with this plugin's platform modules into one predicate. */
function makeExternalJudge(
  original: unknown,
  platform: readonly string[]
): (source: string, importer: string | undefined, isResolved: boolean) => boolean {
  return (source: string, importer: string | undefined, isResolved: boolean): boolean => {
    if (platform.includes(source)) return true
    if (typeof original === 'function') {
      return (original as (s: string, i?: string, r?: boolean) => unknown)(source, importer, isResolved) === true
    }
    if (Array.isArray(original)) return (original as readonly string[]).includes(source)
    if (typeof original === 'string') return original === source
    if (original instanceof RegExp) return original.test(source)
    return false
  }
}

function readManifest(root: string): Record<string, unknown> | undefined {
  try {
    return JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8')) as Record<string, unknown>
  } catch {
    return undefined
  }
}

/** Reads one subpath from exports, tolerating both plain strings and one level of condition objects. */
function resolveExportPath(manifest: Record<string, unknown> | undefined, key: string): string | undefined {
  const exportsField = (manifest?.exports ?? {}) as Record<string, unknown>
  const entry = exportsField[key]
  if (typeof entry === 'string') return entry
  if (typeof entry === 'object' && entry !== null) {
    const record = entry as Record<string, unknown>
    for (const condition of ['default', 'import', 'require']) {
      const value = record[condition]
      if (typeof value === 'string') return value
    }
  }
  return undefined
}

/**
 * The vite build plugin turning a vobs app into a DSH client plugin.
 *
 * It handles the three things plugin authors most often get wrong:
 *   1. **Artifact shape** — automatically wrapped as `window.__ModuleLoader__.load({ id, factory })`;
 *   2. **Artifact purity** — the artifact must be self-contained (single chunk, no standalone
 *      assets, no dynamic import); violations fail the build instead of being discovered
 *      after installation into DSH;
 *   3. **Platform modules** — `react` stays external with the bootstrap injected, never bundled.
 *
 * Usage:
 * ```ts
 * // vite.config.ts
 * import { defineConfig } from 'vite'
 * import { vobsPlugin } from '@vobs/vite-plugin'
 * import { dshBundle } from '@vobs/dsh/vite'
 *
 * export default defineConfig({
 *   plugins: [vobsPlugin(), dshBundle({ entry: 'src/client/index.tsx' })],
 * })
 * ```
 */
export function dshBundle(options: DshBundleOptions = {}): Plugin {
  let fileName = options.fileName ?? 'client.js'
  const platform = [...DEFAULT_PLATFORM_MODULES, ...(options.platformModules ?? [])]
  let root = process.cwd()
  let packageName: string | undefined

  return {
    name: 'vobs:dsh-bundle',

    config(config) {
      const projectRoot = typeof config.root === 'string' ? config.root : process.cwd()
      const build = (config.build ??= {})

      // Infer where the artifact should land from package.json's exports["./client"] —
      // vite defaults to dist/, while the DSH manifest usually points at lib/client.js.
      const declared = resolveExportPath(readManifest(projectRoot), './client')
      if (declared !== undefined) {
        const target = path.resolve(projectRoot, declared.replace(/^\.\//u, ''))
        fileName = path.basename(target)
        const expectedOutDir = path.relative(projectRoot, path.dirname(target)) || '.'
        if (build.outDir === undefined) {
          build.outDir = expectedOutDir
        } else if (path.normalize(String(build.outDir)) !== path.normalize(expectedOutDir)) {
          this.warn(
            `dshBundle: build.outDir is ${String(build.outDir)}, but package.json's exports["./client"] points at ${declared}. ` +
              'When the two disagree, DSH will fail to load the artifact.'
          )
        }
      }

      if (options.entry !== undefined && build.lib === undefined) {
        build.lib = {
          entry: options.entry,
          formats: ['cjs'],
          fileName: () => 'client.cjs'
        }
      }
      build.rollupOptions ??= {}
      build.rollupOptions.external = makeExternalJudge(build.rollupOptions.external, platform)
    },

    configResolved(resolved) {
      root = resolved.root
      const manifest = readManifest(root)
      if (typeof manifest?.name === 'string') packageName = manifest.name

      const dsh = manifest?.dsh as Record<string, unknown> | undefined
      if (manifest !== undefined && dsh?.client === undefined) {
        this.warn(
          'package.json has no dsh.client declaration, so DSH will not treat this package as a client plugin. ' +
            'It needs a shape like { "dsh": { "bundle": { "patch": "./cordis.patch.yml" }, "client": { "platform": "web" } } }.'
        )
      }
    },

    generateBundle(outputOptions, bundle: DshOutputBundle) {
      const items = Object.values(bundle)
      const chunks = items.filter((item): item is DshOutputChunk => item.type === 'chunk')
      const assetNames = items.filter((item): item is DshOutputAsset => item.type === 'asset').map(item => item.fileName)
      const sidecarMaps = assetNames.filter(name => name.endsWith('.map'))
      const foreignAssets = assetNames.filter(name => !name.endsWith('.map'))

      if (foreignAssets.length > 0) {
        this.error(
          `dshBundle: DSH only accepts self-contained single-file bundles, but standalone assets were produced: ${foreignAssets.join(', ')}. ` +
            'Inline CSS as a string (e.g. inject it into the shadow root), or turn off cssCodeSplit.'
        )
      }

      if (chunks.length !== 1) {
        this.error(
          `dshBundle: the artifact must be self-contained, but ${chunks.length} chunks were produced (${chunks.map(c => c.fileName).join(', ')}). ` +
            'Set build.rollupOptions.output.inlineDynamicImports = true and remove dynamic import().'
        )
      }

      if (outputOptions.format !== 'cjs') {
        this.error(
          `dshBundle: DSH's factory protocol requires CJS output, but the current format is ${outputOptions.format}. ` +
            "Set build.lib.formats = ['cjs']."
        )
      }

      /*
       * No import of a non-platform module may survive in the artifact.
       *
       * Judge from chunk metadata, **never by regex over the artifact text** — `@vobs/*`
       * appears inside content as sample code and doc strings (the devkit panel shows vobs
       * import snippets), so text matching mistakes "imports displayed as content" for
       * "dependencies not bundled", failing the build outright.
       */
      const platformSet = new Set(platform)
      const foreignImports = [...new Set(
        chunks.flatMap(item => [...(item.imports ?? []), ...(item.dynamicImports ?? [])])
          .filter(id => !platformSet.has(id))
      )]
      if (foreignImports.length > 0) {
        this.error(
          `dshBundle: the artifact is not self-contained; unbundled dependencies remain: ${foreignImports.join(', ')}. ` +
            "DSH's module loader cannot resolve bare imports — check whether rollupOptions.external externalizes these packages."
        )
      }

      const chunk = chunks[0]
      if (chunk === undefined) return

      for (const map of sidecarMaps) {
        delete bundle[map]
      }
      if (sidecarMaps.length > 0) {
        this.warn('dshBundle: the shell wrapper invalidates sourcemap offsets, so .map artifacts have been dropped; disable build.sourcemap if you need debugging.')
      }

      const id = options.id ?? packageName
      if (id === undefined) {
        this.error('dshBundle: cannot determine the browser module id. Pass one via dshBundle({ id }), or make sure a package.json with a name exists under root.')
      }

      const previousName = chunk.fileName
      chunk.code = wrapAsModuleLoaderFactory(chunk.code, String(id), { react: options.react })
      chunk.map = null
      if (previousName !== fileName) {
        delete bundle[previousName]
        chunk.fileName = fileName
        bundle[fileName] = chunk
      }
    }
  }
}
